Object.assign(SNIP,{});PRESET_NOTES["l14"]={"Ví dụ: Tìm kiếm nhị phân": "Vùng sáng là đoạn [lo, hi] còn có thể chứa x; mỗi vòng nó hẹp đi một nửa. Bật Đoán trước: trước khi tính mid, hãy bấm vào cột bạn nghĩ mid sẽ trỏ tới. Thử nhập 40 (không có).", "Ví dụ: Lower bound tự viết": "Đoạn [lo, hi] luôn chứa đáp án; hi có thể bằng n (khi mọi số đều nhỏ hơn x). Khi a[mid] ≥ x, mid có thể là đáp án nên giữ lại (hi = mid). Kết quả 1.", "Ví dụ: Đếm bằng lower_bound và upper_bound": "Sắp xếp một lần O(n log n), sau đó mỗi câu hỏi đếm chỉ O(log n). Dãy sau sắp xếp: 1 3 3 3 7 9 9 12.", "So sánh: tuần tự và nhị phân trên dãy 1 000 số": "1 000 lần so với 10 lần. Với 10⁹ phần tử, con số là 10⁹ so với 30.", "Lỗi: lo = mid gây lặp vô hạn": "Khi lo = 2, hi = 3: mid = 2, a[2] = 6 < 9 nên lo = mid = 2, không đổi gì. Vòng lặp chạy mãi; trình mô phỏng dừng khi vượt giới hạn số bước."};EX_HINTS["l14"]=[["Dãy đã sắp xếp: mỗi câu hỏi tìm nhị phân O(log n), tổng O(q log n).", "Hoặc dùng binary_search(a, a + n, x) trong <algorithm>."], ["Số phần tử nhỏ hơn x trong dãy đã sắp xếp chính là chỉ số đầu tiên có a[i] ≥ x.", "sort một lần O(n log n), mỗi câu hỏi lower_bound O(log n)."], ["Sau khi sắp xếp, các phần tử thuộc [L, R] nằm liền nhau: từ lower_bound(L) tới trước upper_bound(R).", "Hai iterator trừ nhau ra số phần tử ở giữa."]];
