const PR14=[{label:"Ví dụ: Tìm kiếm nhị phân",input:"23",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};\n    int x;\n    cin >> x;\n    int lo = 0, hi = a.size() - 1, vt = -1;\n    while (lo <= hi) {\n        int mid = (lo + hi) / 2;\n        if (a[mid] == x) {\n            vt = mid;\n            break;\n        }\n        if (a[mid] < x) lo = mid + 1;\n        else hi = mid - 1;\n    }\n    cout << vt << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["lo","mid","hi"],range:["lo","hi"]},{type:"vars",names:["x","vt"]}],predict:[{line:11,v:"mid",q:"mid sẽ trỏ vào ô nào?"}],py:{code:"a = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]\nx = int(input())\nlo, hi = 0, len(a) - 1\nvt = -1\nwhile lo <= hi:\n    mid = (lo + hi) // 2\n    if a[mid] == x:\n        vt = mid\n        break\n    if a[mid] < x:\n        lo = mid + 1\n    else:\n        hi = mid - 1\nprint(vt)",predict:[{line:6,v:"mid",q:"mid sẽ trỏ vào ô nào?"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 2, 5, 8, 12, 16, 23, 38, 56, 72, 91 };\n        int x = int.Parse(Console.ReadLine());\n        int lo = 0, hi = a.Length - 1, vt = -1;\n        while (lo <= hi)\n        {\n            int mid = (lo + hi) / 2;\n            if (a[mid] == x)\n            {\n                vt = mid;\n                break;\n            }\n            if (a[mid] < x) lo = mid + 1;\n            else hi = mid - 1;\n        }\n        Console.WriteLine(vt);\n    }\n}",predict:[{line:12,v:"mid",q:"mid sẽ trỏ vào ô nào?"}]}},{label:"Ví dụ: Lower bound tự viết",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {1, 3, 3, 3, 7, 9, 9, 12};\n    int x = 3;\n    int lo = 0, hi = a.size();\n    while (lo < hi) {\n        int mid = (lo + hi) / 2;\n        if (a[mid] >= x) hi = mid;\n        else lo = mid + 1;\n    }\n    cout << \"Vi tri dau tien >= \" << x << \" la \" << lo << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["lo","mid","hi"],range:["lo","hi"]}],py:{code:"a = [1, 3, 3, 3, 7, 9, 9, 12]\nx = 3\nlo, hi = 0, len(a)\nwhile lo < hi:\n    mid = (lo + hi) // 2\n    if a[mid] >= x:\n        hi = mid\n    else:\n        lo = mid + 1\nprint(\"Vi tri dau tien >=\", x, \"la\", lo)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 1, 3, 3, 3, 7, 9, 9, 12 };\n        int x = 3;\n        int lo = 0, hi = a.Length;\n        while (lo < hi)\n        {\n            int mid = (lo + hi) / 2;\n            if (a[mid] >= x) hi = mid;\n            else lo = mid + 1;\n        }\n        Console.WriteLine(\"Vi tri dau tien >= \" + x + \" la \" + lo);\n    }\n}"}},{label:"Ví dụ: Đếm bằng lower_bound và upper_bound",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> a = {9, 3, 7, 3, 12, 1, 9, 3};\n    sort(a.begin(), a.end());\n    int L = lower_bound(a.begin(), a.end(), 3) - a.begin();\n    int R = upper_bound(a.begin(), a.end(), 3) - a.begin();\n    cout << \"So 3 xuat hien \" << R - L << \" lan\\n\";\n    int t = upper_bound(a.begin(), a.end(), 9) - lower_bound(a.begin(), a.end(), 4);\n    cout << \"Co \" << t << \" so trong [4, 9]\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["L","R"]}],py:{label:"Ví dụ: Đếm bằng bisect_left và bisect_right",code:"from bisect import bisect_left, bisect_right\na = [9, 3, 7, 3, 12, 1, 9, 3]\na.sort()\nL = bisect_left(a, 3)\nR = bisect_right(a, 3)\nprint(\"So 3 xuat hien\", R - L, \"lan\")\nt = bisect_right(a, 9) - bisect_left(a, 4)\nprint(\"Co\", t, \"so trong [4, 9]\")",note:"bisect_left(a, x) là vị trí đầu tiên ≥ x, bisect_right(a, x) là vị trí đầu tiên > x (giống lower_bound, upper_bound của C++). Sắp xếp một lần O(n log n), sau đó mỗi câu hỏi chỉ O(log n)."},cs:{label:"Ví dụ: Đếm bằng LowerBound và UpperBound",code:"using System;\n\nclass Program\n{\n    // chỉ số đầu tiên có a[i] >= x (bằng a.Length nếu không có)\n    static int LowerBound(int[] a, int x)\n    {\n        int lo = 0, hi = a.Length;\n        while (lo < hi)\n        {\n            int mid = lo + (hi - lo) / 2;\n            if (a[mid] >= x) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n\n    // chỉ số đầu tiên có a[i] > x\n    static int UpperBound(int[] a, int x)\n    {\n        int lo = 0, hi = a.Length;\n        while (lo < hi)\n        {\n            int mid = lo + (hi - lo) / 2;\n            if (a[mid] > x) hi = mid;\n            else lo = mid + 1;\n        }\n        return lo;\n    }\n\n    static void Main()\n    {\n        int[] a = { 9, 3, 7, 3, 12, 1, 9, 3 };\n        Array.Sort(a);\n        int L = LowerBound(a, 3);\n        int R = UpperBound(a, 3);\n        Console.WriteLine(\"So 3 xuat hien \" + (R - L) + \" lan\");\n        int t = UpperBound(a, 9) - LowerBound(a, 4);\n        Console.WriteLine(\"Co \" + t + \" so trong [4, 9]\");\n    }\n}",note:"C# không có sẵn lower_bound như C++: Array.BinarySearch chỉ cho một vị trí bất kỳ của x khi x xuất hiện nhiều lần. Vì vậy ta tự viết hai hàm theo mẫu “vị trí đầu tiên thỏa điều kiện”, rồi số phần tử trong [L, R] là UpperBound(R) − LowerBound(L)."}},{label:"So sánh: tuần tự và nhị phân trên dãy 1 000 số",input:"",code:"#include <iostream>\nusing namespace std;\n\nint a[1000];\n\nint main() {\n    int n = 1000;\n    for (int i = 0; i < n; i++) a[i] = 2 * i;\n    int x = 1997;   // không có trong dãy: trường hợp xấu nhất\n    int b1 = 0;\n    for (int i = 0; i < n; i++) {\n        b1++;\n        if (a[i] == x) break;\n    }\n    int lo = 0, hi = n - 1, b2 = 0;\n    while (lo <= hi) {\n        b2++;\n        int mid = (lo + hi) / 2;\n        if (a[mid] == x) break;\n        if (a[mid] < x) lo = mid + 1;\n        else hi = mid - 1;\n    }\n    cout << \"Tuan tu: \" << b1 << \" lan so sanh, nhi phan: \" << b2 << \" lan\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["b1","b2"]}],py:{code:"n = 1000\na = [2 * i for i in range(n)]\nx = 1997   # không có trong dãy: trường hợp xấu nhất\nb1 = 0\nfor i in range(n):\n    b1 += 1\n    if a[i] == x:\n        break\nlo, hi = 0, n - 1\nb2 = 0\nwhile lo <= hi:\n    b2 += 1\n    mid = (lo + hi) // 2\n    if a[mid] == x:\n        break\n    if a[mid] < x:\n        lo = mid + 1\n    else:\n        hi = mid - 1\nprint(\"Tuan tu:\", b1, \"lan so sanh, nhi phan:\", b2, \"lan\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 1000;\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) a[i] = 2 * i;\n        int x = 1997;   // không có trong dãy: trường hợp xấu nhất\n        int b1 = 0;\n        for (int i = 0; i < n; i++)\n        {\n            b1++;\n            if (a[i] == x) break;\n        }\n        int lo = 0, hi = n - 1, b2 = 0;\n        while (lo <= hi)\n        {\n            b2++;\n            int mid = (lo + hi) / 2;\n            if (a[mid] == x) break;\n            if (a[mid] < x) lo = mid + 1;\n            else hi = mid - 1;\n        }\n        Console.WriteLine(\"Tuan tu: \" + b1 + \" lan so sanh, nhi phan: \" + b2 + \" lan\");\n    }\n}"}},{label:"Lỗi: lo = mid gây lặp vô hạn",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {1, 4, 6, 9};\n    int x = 9;\n    int lo = 0, hi = a.size() - 1;\n    while (lo < hi) {\n        int mid = (lo + hi) / 2;\n        if (a[mid] < x) lo = mid;     // sai: phải là mid + 1\n        else hi = mid;\n    }\n    cout << lo << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["lo","mid","hi"],range:["lo","hi"]}],py:{code:"a = [1, 4, 6, 9]\nx = 9\nlo, hi = 0, len(a) - 1\nwhile lo < hi:\n    mid = (lo + hi) // 2\n    if a[mid] < x:\n        lo = mid     # sai: phải là mid + 1\n    else:\n        hi = mid\nprint(lo)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 1, 4, 6, 9 };\n        int x = 9;\n        int lo = 0, hi = a.Length - 1;\n        while (lo < hi)\n        {\n            int mid = (lo + hi) / 2;\n            if (a[mid] < x) lo = mid;     // sai: phải là mid + 1\n            else hi = mid;\n        }\n        Console.WriteLine(lo);\n    }\n}"}}];
