makeEx2(document.getElementById("ex-l14"),sim14,[{t:"Có hay không",d:"Đầu vào: n (1 ≤ n ≤ 10^5), dòng sau n số nguyên đã xếp tăng dần (đôi một khác nhau), rồi q (1 ≤ q ≤ 10^5), dòng cuối q số cần tìm. Đầu ra: một dòng gồm q ký tự, ký tự thứ i là Y nếu số thứ i có trong dãy, N nếu không.",tests:[{in:"5\n1 3 5 7 9\n4\n3 4 9 0",out:"YNYN"},{in:"1\n10\n2\n10 11",out:"YN"},{in:"6\n-10 -5 0 5 10 1000000000\n3\n1000000000 -10 7",out:"YYN"}],start:"#include <iostream>\nusing namespace std;\n\nint a[100000];\n\nint main() {\n    int n;\n    cin >> n;\n    // với mỗi số cần tìm, tìm kiếm nhị phân trên a\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>3*i).join(" ")+"\n"+n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%(3*n)).join(" "),ns:[250,1000,4000],need:"nlogn",limit:n=>14*n*Math.log2(n)+40*n+200,why:"Tìm tuần tự cho mỗi câu hỏi là O(n · q). Dãy đã sắp xếp nên mỗi câu hỏi chỉ cần O(log n)."},py:{start:"n = int(input())\na = list(map(int, input().split()))\nq = int(input())\nxs = list(map(int, input().split()))\n# với mỗi số cần tìm, tìm kiếm nhị phân trên a",hints:["Dãy đã sắp xếp: mỗi câu hỏi tìm nhị phân O(log n), tổng O(q log n).","x in a là tìm tuần tự O(n): quá chậm khi q lớn.","Gom kết quả vào list rồi in một lần bằng \"\".join(kq)."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int q = int.Parse(Console.ReadLine());\n        int[] b = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // với mỗi số cần tìm, tìm kiếm nhị phân trên a\n    }\n}",hints:["Dãy đã sắp xếp: mỗi câu hỏi tìm nhị phân O(log n), tổng O(q log n).","Hoặc dùng Array.BinarySearch(a, x) >= 0 (trả về số âm khi không có x)."]}},{t:"Đếm số nhỏ hơn",d:"Đầu vào: n (1 ≤ n ≤ 10^5), dòng sau n số nguyên (chưa sắp xếp, |aᵢ| ≤ 10^9), rồi q (≤ 10^5), dòng cuối q số x. Đầu ra: với mỗi x, số phần tử của dãy nhỏ hơn hẳn x; các kết quả trên cùng một dòng, cách nhau một khoảng trắng.",tests:[{in:"6\n5 1 4 1 3 9\n4\n1 2 5 10",out:"0 2 4 6"},{in:"1\n7\n2\n7 8",out:"0 1"},{in:"4\n2 2 2 2\n3\n1 2 3",out:"0 0 4"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    // sắp xếp một lần, sau đó mỗi câu hỏi là một lower_bound\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%n).join(" ")+"\n"+n+"\n"+Array.from({length:n},(_,i)=>(i*31)%n).join(" "),ns:[500,2000,8000],need:"nlogn",limit:n=>40*n*Math.log2(n)+200,why:"Đếm bằng cách duyệt cả dãy cho mỗi câu hỏi là O(n · q). Sắp xếp một lần rồi dùng lower_bound."},py:{start:"from bisect import bisect_left\nn = int(input())\na = list(map(int, input().split()))\nq = int(input())\n# sắp xếp một lần, sau đó mỗi câu hỏi là một bisect_left",hints:["Số phần tử nhỏ hơn x trong dãy đã sắp xếp chính là vị trí đầu tiên có a[i] ≥ x: bisect_left(a, x).","a.sort() một lần O(n log n), mỗi câu hỏi O(log n)."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int q = int.Parse(Console.ReadLine());\n        int[] b = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // sắp xếp một lần, sau đó mỗi câu hỏi là một lần tìm “vị trí đầu tiên >= x”\n    }\n}",hints:["Số phần tử nhỏ hơn x trong dãy đã sắp xếp chính là chỉ số đầu tiên có a[i] ≥ x.","Array.Sort một lần O(n log n), mỗi câu hỏi một hàm LowerBound tự viết O(log n)."]}},{t:"Đếm trong khoảng",d:"Đầu vào: n (1 ≤ n ≤ 10^5), dòng sau n số nguyên (|aᵢ| ≤ 10^9), rồi q (≤ 10^5), sau đó q dòng L R (L ≤ R). Đầu ra: với mỗi câu hỏi, số phần tử x của dãy thỏa L ≤ x ≤ R, mỗi kết quả một dòng.",tests:[{in:"7\n9 3 7 3 12 1 9\n3\n3 9\n4 6\n0 100",out:"5\n0\n7"},{in:"1\n5\n2\n5 5\n6 7",out:"1\n0"},{in:"3\n-1000000000 0 1000000000\n1\n-1000000000 1000000000",out:"3"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    // số phần tử trong [L, R] = upper_bound(R) - lower_bound(L)\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%n).join(" ")+"\n"+n+"\n"+Array.from({length:n},(_,i)=>{const a=(i*31)%n;return a+" "+(a+(n>>2))}).join("\n"),ns:[500,2000,8000],need:"nlogn",limit:n=>50*n*Math.log2(n)+200,why:"Duyệt cả dãy cho mỗi câu hỏi là O(n · q). Sắp xếp rồi dùng hai lần tìm nhị phân cho mỗi câu hỏi."},py:{start:"from bisect import bisect_left, bisect_right\nn = int(input())\na = list(map(int, input().split()))\nq = int(input())\n# số phần tử trong [L, R] = bisect_right(a, R) - bisect_left(a, L)",hints:["Sau khi sắp xếp, các phần tử thuộc [L, R] nằm liền nhau: từ bisect_left(a, L) tới trước bisect_right(a, R).","Đếm bằng vòng lặp qua cả dãy cho mỗi câu hỏi là O(n · q)."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int q = int.Parse(Console.ReadLine());\n        // số phần tử trong [L, R] = UpperBound(R) - LowerBound(L)\n    }\n}",hints:["Sau khi sắp xếp, các phần tử thuộc [L, R] nằm liền nhau: từ LowerBound(L) tới trước UpperBound(R).","Viết hai hàm static theo mẫu lower bound: chỉ khác điều kiện a[mid] >= x và a[mid] > x."]}}]);

